-- Public links are immutable text snapshots. Tokens are generated by the server;
-- only SHA-256 digests are stored. No anonymous database grants are required.
begin;
create table public.chat_public_shares (
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references auth.users(id) on delete cascade,
 token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
 title text not null check (char_length(title) between 1 and 200),
 snapshot jsonb not null check (jsonb_typeof(snapshot)='object' and pg_column_size(snapshot)<=524288),
 created_at timestamptz not null default now(),
 expires_at timestamptz not null default now()+interval '30 days',
 revoked_at timestamptz
);
create index chat_public_shares_owner_created_idx on public.chat_public_shares(owner_id,created_at desc);
alter table public.chat_public_shares enable row level security;
revoke all on public.chat_public_shares from public,anon,authenticated;
grant select,insert,update,delete on public.chat_public_shares to service_role;

create function public.read_public_chat_share(p_token_hash text)
returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('title',s.title,'snapshot',s.snapshot,'createdAt',s.created_at,'expiresAt',s.expires_at)
 from public.chat_public_shares s
 where s.token_hash=p_token_hash and s.revoked_at is null and s.expires_at>now()
 and kova_private.auth_user_exists(s.owner_id)
 and not exists(select 1 from public.account_deletion_fences f where f.user_id=s.owner_id)
 limit 1
$$;
revoke all on function public.read_public_chat_share(text) from public,anon,authenticated;
grant execute on function public.read_public_chat_share(text) to service_role;

-- Extend the shared export budget when its canonical foundation is present.
-- Older installations still use the bounded snapshot quota below.
do $guard$
declare body text;
begin
 if to_regprocedure('kova_private.account_export_direct_row_bytes(uuid,bigint)') is not null then
  select pg_get_functiondef('kova_private.account_export_direct_row_bytes(uuid,bigint)'::regprocedure) into body;
  if position('(''chat_public_shares'', ''owner_id'')' in body)=0 then
   if position('(''chat_share_links'', ''user_id'')' in body)=0 then
    raise exception 'public_share_export_registry_mismatch';
   end if;
   execute replace(body, '(''chat_share_links'', ''user_id'')', '(''chat_share_links'', ''user_id''), (''chat_public_shares'', ''owner_id'')');
  end if;
 end if;
end $guard$;

create function kova_private.guard_public_chat_share()
returns trigger language plpgsql security definer set search_path='' as $$
declare used_bytes bigint; link_count integer; total_bytes bigint;
begin
 if tg_op='UPDATE' then
  if (new.id,new.owner_id,new.token_hash,new.title,new.snapshot,new.created_at,new.expires_at)
    is distinct from (old.id,old.owner_id,old.token_hash,old.title,old.snapshot,old.created_at,old.expires_at) then
   raise exception 'public_share_snapshot_immutable';
  end if;
  return new;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text,20260903204500));
 if not kova_private.auth_user_exists(new.owner_id) or exists(select 1 from public.account_deletion_fences where user_id=new.owner_id) then
  raise exception 'public_share_account_unavailable';
 end if;
 delete from public.chat_public_shares where owner_id=new.owner_id and (revoked_at is not null or expires_at<=now());
 select count(*),coalesce(sum(octet_length(to_jsonb(s)::text)),0) into link_count,used_bytes
 from public.chat_public_shares s where owner_id=new.owner_id;
 if link_count>=20 or used_bytes+octet_length(to_jsonb(new)::text)>1048576 then
  raise exception 'public_share_limit';
 end if;
 if to_regprocedure('kova_private.account_export_direct_row_bytes(uuid,bigint)') is not null then
  execute 'select kova_private.account_export_direct_row_bytes($1,52428800)' into total_bytes using new.owner_id;
  if total_bytes+octet_length(to_jsonb(new)::text)+512>52428800 then raise exception 'public_share_limit'; end if;
 end if;
 return new;
end;
$$;
revoke all on function kova_private.guard_public_chat_share() from public,anon,authenticated;
grant execute on function kova_private.guard_public_chat_share() to service_role;
create trigger chat_public_shares_guard before insert or update on public.chat_public_shares
 for each row execute function kova_private.guard_public_chat_share();
commit;
